PRAGMA foreign_keys = ON;
CREATE TABLE imports (id INTEGER PRIMARY KEY, name TEXT NOT NULL, source_path TEXT NOT NULL, encoding TEXT NOT NULL, delimiter TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE import_rows (id INTEGER PRIMARY KEY, import_id INTEGER NOT NULL REFERENCES imports(id) ON DELETE CASCADE, row_number INTEGER NOT NULL, artist TEXT NOT NULL, title TEXT NOT NULL, version TEXT, label TEXT, bpm REAL, musical_key TEXT, duration TEXT, original_json TEXT NOT NULL, selected_seed INTEGER NOT NULL DEFAULT 0 CHECK(selected_seed IN (0,1)), UNIQUE(import_id,row_number));
CREATE TABLE source_tracks (id INTEGER PRIMARY KEY, provider TEXT NOT NULL, provider_id TEXT NOT NULL, artist TEXT NOT NULL, title TEXT NOT NULL, version TEXT, adapter_version TEXT NOT NULL, UNIQUE(provider,provider_id));
CREATE TABLE seed_matches (id INTEGER PRIMARY KEY, import_row_id INTEGER NOT NULL REFERENCES import_rows(id) ON DELETE CASCADE, source_track_id INTEGER REFERENCES source_tracks(id), status TEXT NOT NULL CHECK(status IN ('pending','accepted','skipped')), confidence REAL, matched_manually INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE discovery_runs (id INTEGER PRIMARY KEY, import_id INTEGER NOT NULL REFERENCES imports(id), status TEXT NOT NULL, stage TEXT NOT NULL, settings_json TEXT NOT NULL, adapter_version TEXT NOT NULL, ranking_version TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE jobs (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES discovery_runs(id) ON DELETE CASCADE, job_key TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, payload_json TEXT NOT NULL, last_error TEXT, UNIQUE(run_id,job_key));
CREATE TABLE tracklists (id INTEGER PRIMARY KEY, provider TEXT NOT NULL, provider_id TEXT NOT NULL, url TEXT NOT NULL, title TEXT, dj_name TEXT, played_at TEXT, adapter_version TEXT NOT NULL, fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(provider,provider_id));
CREATE TABLE tracklist_entries (id INTEGER PRIMARY KEY, tracklist_id INTEGER NOT NULL REFERENCES tracklists(id) ON DELETE CASCADE, position INTEGER NOT NULL, source_track_id INTEGER REFERENCES source_tracks(id), display_text TEXT NOT NULL, cue_seconds INTEGER, UNIQUE(tracklist_id,position));
CREATE TABLE recommendations (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES discovery_runs(id) ON DELETE CASCADE, source_track_id INTEGER NOT NULL REFERENCES source_tracks(id), score REAL NOT NULL, components_json TEXT NOT NULL, ranking_version TEXT NOT NULL, UNIQUE(run_id,source_track_id));
CREATE TABLE page_cache (id INTEGER PRIMARY KEY, cache_key TEXT NOT NULL UNIQUE, source_type TEXT NOT NULL, response_json TEXT NOT NULL, adapter_version TEXT NOT NULL, fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TEXT);
CREATE INDEX idx_rows_import ON import_rows(import_id); CREATE INDEX idx_jobs_run_status ON jobs(run_id,status); CREATE INDEX idx_entries_track ON tracklist_entries(source_track_id);
